import{R as r,e as a,f as i,U as s}from"./chunks/framework.BKStFnx-.js";const u=JSON.parse('{"title":"UI reference","description":"","frontmatter":{},"headers":[],"relativePath":"browser/ui-reference/index.md","filePath":"browser/ui-reference/index.md","lastUpdated":1780377007000}'),o={name:"browser/ui-reference/index.md"};function t(n,e,l,d,c,h){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="ui-reference" tabindex="-1">UI reference <a class="header-anchor" href="#ui-reference" aria-label="Permalink to &quot;UI reference&quot;">​</a></h1><p>This section is the canonical visual and structural reference for the browser-owned Formie UI surface.</p><p>Use it to inspect how fields and shared components look, which classes and <code>data-formie-*</code> hooks they expose, and which CSS variables are intended for styling overrides.</p><p>This area is owned by <code>@verbb/formie-browser</code> because that package owns:</p><ul><li>the default rendered HTML structure</li><li>the shared CSS bundles and theme classes</li><li>browser state attributes such as loading, error, page, and tab markers</li><li>field and component contracts used across Craft-rendered and browser-managed forms</li></ul><p>Framework package docs should link back here when they are using the same browser-owned markup and styling contracts.</p><h2 id="in-this-section" tabindex="-1">In this section <a class="header-anchor" href="#in-this-section" aria-label="Permalink to &quot;In this section&quot;">​</a></h2><ul><li><a href="/formie/browser/ui-reference/fields/">Fields</a></li><li><a href="/formie/browser/ui-reference/fields/single-line-text">Single Line Text</a></li><li><a href="/formie/browser/ui-reference/fields/address">Address</a></li><li><a href="/formie/browser/ui-reference/components/">Components</a></li><li><a href="/formie/browser/ui-reference/components/buttons">Buttons</a></li><li><a href="/formie/browser/ui-reference/components/loading">Loading</a></li><li><a href="/formie/browser/ui-reference/css-variables">CSS variables</a></li></ul><h2 id="how-to-use-these-pages" tabindex="-1">How to use these pages <a class="header-anchor" href="#how-to-use-these-pages" aria-label="Permalink to &quot;How to use these pages&quot;">​</a></h2><p>Field and component pages are designed to answer four questions:</p><ul><li>what the default UI looks like</li><li>which attributes are required for browser behavior</li><li>which classes are optional styling hooks</li><li>which CSS variables and browser states are safe to target</li></ul><p>If you need browser lifecycle, module, or submit behavior, use the main Browser docs:</p><ul><li><a href="/formie/browser/behavior/javascript-events">JavaScript events</a></li><li><a href="/formie/browser/">JavaScript API</a></li><li><a href="/formie/browser/behavior/submission-handling">Submission handling</a></li></ul>',13)])])}const b=r(o,[["render",t]]);export{u as __pageData,b as default};
